select s.role, count(distinct s.id) users_with_all_payroll_rights from staff s join organizations o on o.id=s.organization_id where o.business_type='school' and s.role in ('bursar','assistant_bursar','assistant_bursar_com') and not exists (select 1 from unnest(array['payroll_prepare','payroll_approve','payroll_post']) k where not coalesce((select allowed from staff_permission_overrides p where p.organization_id=o.id and p.staff_id=s.id and p.permission_key=k),(select allowed from organization_permissions p where p.organization_id=o.id and p.role_key=s.role and p.permission_key=k),false)) group by s.role;
